WITH recent_products AS (SELECT *, cost - stock_qty AS cost_minus_stock_qty FROM products WHERE product_name LIKE '%Maker%'), products_stats AS (SELECT category, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(category))) AS category_values, COUNT(CASE WHEN brand = 'Acme' THEN 1 END) AS acme_count FROM recent_products GROUP BY category) SELECT category, category_values, acme_count FROM products_stats WHERE acme_count < 4 ORDER BY category_values DESC
